package com.coraline.tycoon;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraftforge.gametest.*;

/** Real registry/world fixtures and deterministic data checks; not visual claims. */
@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class TycoonPhaseTwoGameTests {
    @GameTest(template="empty") public static void naturallyChangedGeneratedSoilAllowsUpgradeButPlayerEditStillBlocks(GameTestHelper t){
        var p=player(t,true);try{var h=TycoonWorld.home(p);p.getInventory().setItem(0,new ItemStack(TycoonContent.VOID_POWER.get(),64));
            for(int i=0;i<2;i++){
                var at=h.center().offset(7+i,-1,7);var expected=(i==0?Blocks.GRASS_BLOCK:Blocks.DIRT).defaultBlockState();var actual=(i==0?Blocks.DIRT:Blocks.GRASS_BLOCK).defaultBlockState();p.serverLevel().setBlock(at,actual,2);
                var terrain=new CompoundTag();terrain.put("0,0",TycoonLandscape.encode(Map.of(at,expected),h.center()));h.state.put("Terrain",terrain);
                String result=TycoonBuildJob.begin(p,"Comfortable House",new CompoundTag(),Map.of(at,Blocks.SPRUCE_PLANKS.defaultBlockState()),h.center().asLong(),new CompoundTag(),8);
                t.assertTrue(result.startsWith("Building")&&h.state.contains("BuildJob"),"Natural generated soil drift blocks upgrade: "+result);
                t.assertTrue(TycoonLandscape.decode(p.serverLevel(),h.state.getCompound("BuildJob").getCompound("Before")).get(at).equals(actual),"Rollback snapshot did not retain actual naturally changed soil");
                TycoonBuildJob.rollback(p,"QA stopped uncommitted job");TycoonPhaseTwo.edit(p,at,actual);
                result=TycoonBuildJob.begin(p,"Comfortable House",new CompoundTag(),Map.of(at,Blocks.SPRUCE_PLANKS.defaultBlockState()),h.center().asLong(),new CompoundTag(),8);
                t.assertTrue(result.contains("conflicts")&&!h.state.contains("BuildJob")&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==64&&p.serverLevel().getBlockState(at).equals(actual),"Natural-soil exception bypassed real player-edit protection: "+result);
                h.state.remove("PlayerEdits");p.serverLevel().setBlock(at,Blocks.AIR.defaultBlockState(),2);
            }
            t.assertFalse(TycoonBuildJob.generatedMatch(Blocks.GOLD_BLOCK.defaultBlockState(),Blocks.GRASS_BLOCK.defaultBlockState()),"Unrelated player material accepted as generated soil");
        }finally{clean(p);}t.succeed();
    }
    private static ServerPlayer player(GameTestHelper t){return player(t,false);}
    private static ServerPlayer player(GameTestHelper t,boolean personal){var server=t.getLevel().getServer();var level=personal?server.getLevel(TycoonWorld.KEY):server.overworld();var p=new ServerPlayer(server,level,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"TycoonTwoQA"));p.connection=new net.minecraft.server.network.ServerGamePacketListenerImpl(server,new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);var h=TycoonWorld.home(p);h.state.putBoolean("Activated",true);p.setPos(personal?h.center().getCenter():t.absolutePos(new BlockPos(2,2,2)).getCenter());return p;}
    private static void clean(ServerPlayer p){TycoonVisitTickets.release(p.server,TycoonWorld.home(p));TycoonData.get(p.server).homes.remove(p.getUUID());TycoonNetwork.clear(p.getUUID());TycoonBuildJob.clear(p.getUUID());}
    private static TycoonData.Resident resident(ServerPlayer p){var r=TycoonCare.generate(UUID.randomUUID());r.n.putString("Status","ACTIVE");r.n.putLong("Bed",p.blockPosition().asLong());TycoonWorld.home(p).residents.put(r.id,r);return r;}
    @GameTest(template="empty") public static void firstVisitInitializesExactlyHalfSuspicionOnlyOnce(GameTestHelper t){var r=TycoonCare.generate(UUID.randomUUID());t.assertTrue(TycoonDialogue.initialize(r)&&TycoonDialogue.suspicion(r)==.5&&TycoonDialogue.trust(r)==TycoonPhaseTwoConfig.INITIAL_TRUST.get(),"First relationship values are not exactly the specified defaults");TycoonDialogue.set(r,.4,.3);t.assertFalse(TycoonDialogue.initialize(r),"Later visit reinitialized relationship");t.assertTrue(TycoonDialogue.trust(r)==.4&&TycoonDialogue.suspicion(r)==.3,"Returning visit lost saved relationship");t.succeed();}

    @GameTest(template="empty") public static void sixteenBySixteenMapAndAdjacencyCannotExpandForever(GameTestHelper t){var h=new TycoonData().home(UUID.randomUUID());int count=0;for(int x=-10;x<10;x++)for(int z=-10;z<10;z++)if(TycoonLandscape.inBounds(x,z))count++;t.assertTrue(count==256,"Expansion cap isn't exactly256 chunks");t.assertTrue(TycoonLandscape.adjacent(h,0,0)&&TycoonLandscape.adjacent(h,-1,-1),"Core-adjacent purchase unavailable");t.assertFalse(TycoonLandscape.adjacent(h,3,3)||TycoonLandscape.inBounds(8,0)||TycoonLandscape.inBounds(-9,0),"Disconnected/outside land accepted");var tile=new CompoundTag();tile.putInt("Tier",1);var owned=new CompoundTag();owned.put("0,0",tile);h.state.put("Terrain",owned);t.assertTrue(TycoonLandscape.adjacent(h,1,0)&&!TycoonLandscape.adjacent(h,1,1),"New land doesn't require cardinal adjacency");t.succeed();}

    @GameTest(template="empty") public static void proceduralTiersCodecCoreAndBoundaryHeightsAreReal(GameTestHelper t){var p=player(t,true);try{var h=TycoonWorld.home(p);var l=p.serverLevel();var signatures=new HashSet<Object>();for(int tier=0;tier<6;tier++){var plan=TycoonLandscape.terrain(h,1,0,tier);var encoded=TycoonLandscape.encode(plan,h.center().offset(16,0,0));t.assertTrue(TycoonLandscape.decode(l,encoded).equals(plan),"Generated-cell codec lost states/positions");signatures.add(new HashSet<>(plan.values()));t.assertTrue(plan.keySet().stream().noneMatch(at->TycoonLandscape.core(h,at)),"Terrain plan overwrites core");}t.assertTrue(signatures.size()==6,"Terrain tiers are equivalent palettes");var heights=new HashSet<Integer>();int maxStep=0;for(int x=-48;x<48;x++)for(int z=-32;z<32;z++){heights.add(TycoonLandscape.height(h,x,z));maxStep=Math.max(maxStep,Math.abs(TycoonLandscape.height(h,x,z)-TycoonLandscape.height(h,x+1,z)));}t.assertTrue(heights.size()>2&&maxStep<=2,"Terrain is flat or chunk-edge discontinuity exceeds walkable steps");t.assertTrue(TycoonLandscape.terrain(h,1,0,3).equals(TycoonLandscape.terrain(h,1,0,3)),"Terrain generation isn't deterministic");}finally{clean(p);}t.succeed();}

    @GameTest(template="empty") public static void goodnessRequiresQualityCoverageAndIsBounded(GameTestHelper t){var h=new TycoonData().home(UUID.randomUUID());t.assertTrue(TycoonLandscape.goodness(h).total()==0,"Empty core starts with high Goodness");var owned=new CompoundTag();var beautiful=new CompoundTag();beautiful.putInt("Tier",5);owned.put("0,0",beautiful);h.state.put("Terrain",owned);TycoonLandscape.recalculate(h);double one=TycoonLandscape.goodness(h).terrain();t.assertTrue(one>0&&one<10,"One beautiful tile maxed out terrain Goodness");for(int x=-8;x<8;x++)for(int z=-8;z<8;z++)owned.put(TycoonLandscape.key(x,z),beautiful.copy());h.state.putInt("HouseTier",5);h.state.putInt("SkyTier",5);TycoonLandscape.recalculate(h);var quality=TycoonLandscape.goodness(h);t.assertTrue(quality.total()>95&&quality.total()<=100&&quality.house()==30&&quality.sky()==15,"Goodness weights/cap incorrect");t.succeed();}

    @GameTest(template="empty") public static void failedGenerationPreservesCurrencyAndProtectedConstruction(GameTestHelper t){var p=player(t,true);try{var h=TycoonWorld.home(p);TycoonWorld.prepare(p);p.getInventory().setItem(0,new ItemStack(TycoonContent.VOID_POWER.get(),64));var plan=TycoonLandscape.terrain(h,0,0,1);var at=plan.keySet().iterator().next();p.serverLevel().setBlock(at,Blocks.GOLD_BLOCK.defaultBlockState(),2);String result=TycoonLandscape.purchase(p,0,0,1);t.assertTrue(result.contains("conflicts")&&p.serverLevel().getBlockState(at).is(Blocks.GOLD_BLOCK)&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==64&&!h.state.contains("BuildJob"),"Generation overwrote protected construction or spent on failure: "+result);t.assertTrue(p.serverLevel().getBlockState(h.center().offset(1,0,-1)).is(TycoonContent.DESK.get()),"Failed generation damaged Work Desk");}finally{clean(p);}t.succeed();}

    @GameTest(template="empty") public static void terrainUpgradePreservesCanonicalHouseButRejectsChangedHouseCells(GameTestHelper t){
        var p=player(t,true);try{var h=TycoonWorld.home(p);var l=p.serverLevel();TycoonWorld.prepare(p);p.getInventory().setItem(0,new ItemStack(TycoonContent.VOID_POWER.get(),64));
            var at=h.center().offset(5,0,5);var house=Map.of(at,Blocks.OAK_PLANKS.defaultBlockState(),at.above(),Blocks.AIR.defaultBlockState());
            house.forEach((pos,state)->l.setBlock(pos,state,2));h.state.put("HouseGenerated",TycoonLandscape.encode(house,h.center()));
            var next=Map.of(at,Blocks.DIRT.defaultBlockState(),at.above(),Blocks.OAK_LOG.defaultBlockState());
            String result=TycoonBuildJob.begin(p,"terrain 0,0",new CompoundTag(),next,h.center().asLong(),new CompoundTag(),1);
            t.assertTrue(result.startsWith("Building")&&TycoonLandscape.decode(l,h.state.getCompound("BuildJob").getCompound("After")).isEmpty(),"Terrain upgrade overwrites/refuses canonical house or plants a tree in its interior: "+result);
            h.state.remove("BuildJob");l.setBlock(at,Blocks.GOLD_BLOCK.defaultBlockState(),2);
            result=TycoonBuildJob.begin(p,"terrain 0,0",new CompoundTag(),next,h.center().asLong(),new CompoundTag(),1);
            t.assertTrue(result.contains("conflicts")&&!h.state.contains("BuildJob")&&l.getBlockState(at).is(Blocks.GOLD_BLOCK)&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==64,"Terrain upgrade adopted changed house cells or spent on refusal: "+result);
        }finally{clean(p);}t.succeed();
    }

    @GameTest(template="empty") public static void houseTiersPreserveTheCoreAndGrowInComplexity(GameTestHelper t){var h=new TycoonData().home(UUID.randomUUID());int before=0;for(int tier=1;tier<=5;tier++){var plan=TycoonHouses.plan(h,tier);t.assertTrue(plan.size()>before,"Higher house tier isn't larger/more detailed");before=plan.size();t.assertFalse(plan.containsKey(h.center().offset(1,0,-1))||plan.containsKey(h.center().offset(-1,0,-1)),"House plan replaces desk or return door");t.assertTrue(plan.values().stream().anyMatch(s->s.is(Blocks.LANTERN)||s.is(Blocks.SEA_LANTERN)),"House has no actual lighting");}t.succeed();}

    @GameTest(template="empty") public static void dollsAreSeparateOwnerResidentCapabilitiesAndCannotSpendWhenFull(GameTestHelper t){var p=player(t);try{var h=TycoonWorld.home(p);var r=resident(p);p.getInventory().setItem(0,new ItemStack(TycoonContent.VOID_POWER.get(),64));for(int i=1;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.STONE,64));String result=TycoonDolls.craft(p,r.id,false);t.assertTrue(result.contains("Free")&&TycoonShop.count(p,TycoonContent.VOID_POWER.get())==64&&!r.n.getCompound("Doll").hasUUID("Id"),"Full-inventory doll crafting spent or assigned a hidden doll");var doll=new CompoundTag();doll.putUUID("Id",UUID.randomUUID());doll.putString("Status","INVENTORY");r.n.put("Doll",doll);var item=TycoonDolls.item(p,r,doll);t.assertTrue(item.is(TycoonPhaseTwoContent.DOLL.get())&&!item.is(com.coraline.registry.ModItems.DOLL.get()),"Personalized doll reused main-story Bound Doll");t.assertTrue(item.getTag().getUUID("Resident").equals(r.id)&&item.getTag().getUUID("TycoonOwner").equals(p.getUUID())&&TycoonDolls.matches(r,item.getTag().getUUID("Doll")),"Doll identity is display-name based or ownerless");}finally{clean(p);}t.succeed();}

    @GameTest(template="empty") public static void wrongResidentDollHandoffDoesNotConsumeOrPlace(GameTestHelper t){var p=player(t);TycoonNpc actor=null;try{var first=resident(p);var other=resident(p);var doll=new CompoundTag();doll.putUUID("Id",UUID.randomUUID());doll.putString("Status","INVENTORY");first.n.put("Doll",doll);p.setItemInHand(InteractionHand.MAIN_HAND,TycoonDolls.item(p,first,doll));actor=TycoonContent.NPC.get().create(p.serverLevel());actor.configure(p.getUUID(),other.id,false,other.n.getInt("Appearance"));actor.setPos(p.position());p.serverLevel().addFreshEntity(actor);t.assertTrue(TycoonDolls.give(p,actor)&&p.getMainHandItem().getCount()==1&&!other.n.getCompound("Doll").hasUUID("Entity"),"Wrong child accepted/consumed another resident's doll");}finally{if(actor!=null)actor.discard();clean(p);}t.succeed();}

    @GameTest(template="empty") public static void nighttimeUsesOverworldTimeAndRelationshipsStayHidden(GameTestHelper t){var p=player(t,true);long time=p.server.overworld().getDayTime();try{p.server.overworld().setDayTime(6000);t.assertFalse(TycoonVisits.nighttime(p),"Daytime mice allowed");p.server.overworld().setDayTime(13000);t.assertTrue(TycoonVisits.nighttime(p),"Nighttime checked white-void time instead of Overworld");var r=resident(p);r.n.putBoolean("RelationshipInitialized",true);TycoonDialogue.set(r,.1,.5);var visit=new CompoundTag();visit.putString("Phase","INSIDE");r.n.put("Visit",visit);var snapshot=new CompoundTag();TycoonPhaseTwoMenus.enrich(p,"visitor",r.id,snapshot);t.assertFalse(snapshot.contains("Trustness")||snapshot.contains("Suspicion"),"Ordinary dialogue leaks exact hidden relationships");t.assertTrue(TycoonDialogue.trust(r)==.1&&TycoonDialogue.suspicion(r)==.5,"Opening first dialogue changed mandatory starting values");}finally{p.server.overworld().setDayTime(time);clean(p);}t.succeed();}

    @GameTest(template="empty") public static void dialogueOutcomesVaryByPersonalityAndCannotReplay(GameTestHelper t){var p=player(t,true);try{var r=resident(p);var visit=new CompoundTag();visit.putString("Phase","INSIDE");r.n.put("Visit",visit);TycoonDialogue.set(r,.1,.5);var first=TycoonDialogue.open(p,r);String answer=TycoonDialogue.respond(p,r,first.getUUID("Question"),0);double trust=TycoonDialogue.trust(r),suspicion=TycoonDialogue.suspicion(r);t.assertTrue(trust>.1&&suspicion<.5,"Honest response had no distinct effect: "+answer);TycoonDialogue.respond(p,r,first.getUUID("Question"),0);t.assertTrue(trust==TycoonDialogue.trust(r)&&suspicion==TycoonDialogue.suspicion(r),"Repeated response replayed relationship rewards");TycoonWorld.home(p).state.putLong("ActiveTicks",220);var next=TycoonDialogue.open(p,r);TycoonDialogue.respond(p,r,next.getUUID("Question"),2);t.assertTrue(TycoonDialogue.trust(r)<trust&&TycoonDialogue.suspicion(r)>suspicion,"Harsh response equals reassuring outcome");t.assertTrue(r.n.getList("DialogueHistory",10).size()==2,"Conversation history lost or duplicated");}finally{clean(p);}t.succeed();}

    @GameTest(template="empty") public static void visitorDataAndPurchasedWorldSurviveIndependentSaveLoad(GameTestHelper t){var data=new TycoonData();var h=data.home(UUID.randomUUID());var r=TycoonCare.generate(UUID.randomUUID());r.n.putString("Status","ACTIVE");r.n.putBoolean("RelationshipInitialized",true);TycoonDialogue.set(r,.36,.42);var visit=new CompoundTag();visit.putString("Phase","INSIDE");visit.putUUID("Session",UUID.randomUUID());visit.putLong("LeaveAfter",17000);r.n.put("Visit",visit);h.residents.put(r.id,r);h.state.putInt("SkyTier",4);h.state.putInt("HouseTier",3);h.state.putBoolean("VisitActive",true);var owned=new CompoundTag();var tile=new CompoundTag();tile.putInt("Tier",3);owned.put("0,0",tile);h.state.put("Terrain",owned);var snapshot=data.save(new CompoundTag());var restored=TycoonData.load(snapshot);t.assertTrue(snapshot.equals(restored.save(new CompoundTag())),"Phase2 state changed on reload");var loaded=restored.home(h.owner).residents.get(r.id);t.assertTrue(TycoonDialogue.suspicion(loaded)==.42&&TycoonVisits.inside(loaded),"Returning visit reset relationship or identity");t.succeed();}
}
